    """
    Check if the parentheses in the string are balanced.

    Args:
    s (str): The string containing parentheses to check.

    Returns:
    bool: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in mapping.values():
            stack.append(char)
